window.bookSummaryJSON = "<p>Experience one of television’s greatest science-fiction series: <i>The Twilight Zone</i> - fully dramatized for audio! Featuring a full cast, music and sound effects, and today’s biggest celebrities in modern radio dramatizations. </p> <p></p>The first human to visit Mars is relieved to find that the Martians treat him kindly and have even built him a house like his home on Earth - but with one big difference. <p></p>"; 
